-- ============================================================================
-- Lote 1 · 1.5 — Programación histórica 2026-1 y 2026-V1 (575 franjas)
--
-- Registro HISTÓRICO. Deliberadamente SIN CLAVES FORÁNEAS:
--   · no referencia academic_work_plan.asignatura
--   · no referencia auth.personas
--
-- ⚠️ POR QUÉ SIN FK A ASIGNATURA: `cod_asigna` del origen (APT_52, AP_35,
-- EP_37D) NO es un código de materia, es PROGRAMA_PENSUM — todas las filas de
-- APT pensum 52 comparten el mismo valor. No identifica la asignatura, así que
-- no hay mapeo que construir: el dato no existe en el origen.
--
-- ⚠️ `id_asignatura_sugerido` es SUGERENCIA, NUNCA AUTORIDAD. Emparejamiento
-- best-effort por nombre normalizado, desempatando por semestre:
--   475 / 575 filas obtuvieron sugerencia
--     4 de ellas resolvieron nombre + semestre unívocamente
--   100 quedaron en NULL
-- No debe usarse para decidir nada sin validación humana.
--
-- ⚠️ `grupo_original` se guarda VERBATIM. Etiquetas presentes: A, B, C, I, V.
-- No se renombran ni se normalizan: son la marca del origen.
--
-- ⚠️ Esta tabla NO pasa por el guard de publicación de NUEVA-1. Si pasara, las
-- 71 franjas con cruce del histórico nunca podrían entrar — y el objetivo es
-- exactamente exponerlas como hallazgo, no como error del sistema.
--
-- Reparto por oferta: OFERTA REGULAR=535, ESTRATEGIA VIRTUAL=40.
-- Todas son de Sede Central, así que no dependen del catálogo de CETAPs.
--
-- Forward-only e idempotente. SQL puro.
-- ============================================================================

CREATE TABLE IF NOT EXISTS "academic-schedule".programacion_historica (
    id                     BIGSERIAL PRIMARY KEY,
    periodo                VARCHAR(20),
    tipo_oferta            VARCHAR(40),
    cod_sede               VARCHAR(10),
    seccional              VARCHAR(80),
    sede                   VARCHAR(80),
    pensum                 VARCHAR(10),
    programa               VARCHAR(20),
    cod_asigna             VARCHAR(30),
    asignatura             VARCHAR(200),
    detalle_asignatura     TEXT,
    creditos               SMALLINT,
    semestre               SMALLINT,
    horas                  SMALLINT,
    grupo_original         VARCHAR(10),
    jornada                VARCHAR(30),
    cedula_docente         VARCHAR(20),
    nombre_docente         VARCHAR(150),
    vinculacion_docente    VARCHAR(40),
    fecha_inicio           VARCHAR(20),
    fecha_fin              VARCHAR(20),
    dia                    VARCHAR(15),
    hora_inicio            VARCHAR(10),
    hora_fin               VARCHAR(10),
    hrs_clase              VARCHAR(10),
    aula                   VARCHAR(60),
    estado_aula            VARCHAR(20),
    estado_docente         VARCHAR(20),
    id_asignatura_sugerido BIGINT,
    importado_en           TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE "academic-schedule".programacion_historica IS
  'Programación 2026-1 y 2026-V1 tal como llegó. Sin FK: cod_asigna es PROGRAMA_PENSUM, no código de materia. No pasa por el guard de publicación.';
COMMENT ON COLUMN "academic-schedule".programacion_historica.id_asignatura_sugerido IS
  'SUGERENCIA best-effort por nombre normalizado + semestre. Nunca autoritativa.';
COMMENT ON COLUMN "academic-schedule".programacion_historica.grupo_original IS
  'Etiqueta de grupo del origen, VERBATIM (A/B/C/I/V). No renombrar.';

