-- Canario: el conteo exacto y que no se perdió ninguna etiqueta de grupo.
DO $$
DECLARE
  v_total INT; v_sug INT; v_grupos INT;
BEGIN
  SELECT COUNT(*) INTO v_total FROM "academic-schedule".programacion_historica;
  SELECT COUNT(*) INTO v_sug   FROM "academic-schedule".programacion_historica WHERE id_asignatura_sugerido IS NOT NULL;
  SELECT COUNT(DISTINCT grupo_original) INTO v_grupos
    FROM "academic-schedule".programacion_historica WHERE grupo_original IS NOT NULL;

  RAISE NOTICE '022: franjas=% con_sugerencia=% etiquetas_grupo=%', v_total, v_sug, v_grupos;

  IF v_total <> 575 THEN
    RAISE EXCEPTION '022: se esperaban 575 franjas y hay %', v_total;
  END IF;
  IF v_grupos <> 5 THEN
    RAISE EXCEPTION '022: se esperaban 5 etiquetas de grupo y hay %', v_grupos;
  END IF;
END $$;
